head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vSecugrpID = "";
scwin.list_dtl_noti_id;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        if (js_market === "1" || js_market === "2") {
            panel_mkt_gubun.hide();
            $c.cm.setColumnProp(grd_dataList, "SPOT_ISU_TRD_MKT_TP_CD", "Show", false);
        } else {
            panel_mkt_gubun.show("");
        }
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 1));
        edt_EDate.setValue(vCurDate);
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
        await scwin.listSync();
        $c.cm.fn_com_isur(txb_com_cd, txb_com_nm);
        await scwin.depouserReadSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40300.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40300.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_com_cd_onkeyup
 * @description txb_com_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_com_cd_onkeyup = function() {
    try {
        if (txb_com_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40300.txb_com_cd_onkeyup" });
    }
};

/**
 * @method
 * @name txb_com_cd_onfocus
 * @description txb_com_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_com_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40300.txb_com_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_com_cd_onblur
 * @description txb_com_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_com_cd_onblur = function() {
    try {
        if (txb_com_cd.getValue() === "") {
            txb_com_nm.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40300.txb_com_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_com_cd_onblur
 * @description txb_com_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_com_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_com_cd.getValue() === "") {
            txb_com_nm.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40300.txb_com_cd_onblur" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40300.Grd_com_isur_OnKeyPress" });
    }
};

