    try {
        await $c.win.alert(dts_consultationBookList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40300.dts_consultationBookList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_consultationBookList_OnLoadCompleted
 * @description dts_consultationBookList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_consultationBookList_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount <= 0) {
            dts_consultationBookList.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40300.dts_consultationBookList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40300.btn_SDate_onclick" });
    }
};

/**
 * @method
