/**
 * @method
 * @name btn_select_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_select_onclick = async function() {
    try {
        if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40300.btn_select_onclick" });
    }
};

/**
 * @method
 * @name btn_toexcel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_toexcel_onclick = function() {
    try {
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF40300.xml", SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_dataList, {fileName: "상장알림통보내역", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40300.btn_toexcel_onclick" });
    }
};

/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_close_onclick = function() {
    try {
        self.close();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40300.btn_close_onclick" });
    }
};

/**
 * @method
 * @name btn_input_onclick
 * @description 「입력」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_input_onclick = async function() {
    try {
        scwin.list_dtl_noti_id = "input";
        const options = {
            id: "ULDSTF40301",
            title: "상장알림 등록",
            type: "browserPopup",
            width: "690px",
            height: "350px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/lstmgt/ULDSTF40301.gfm", options);
        scwin.list_dtl_noti_id = "";
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40300.btn_input_onclick" });
    }
};

/**
 * @method
 * @name grd_dataList_OnDblClick
 * @description grd_dataList 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_dataList_OnDblClick = async function(row, colid) {
    try {
        const options = {
            id: "ULDSTF40301",
            title: "상장알림 수정",
            type: "browserPopup",
            width: "690px",
            height: "350px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/lstmgt/ULDSTF40301.gfm", options);
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40300.grd_dataList_OnDblClick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40300.cmb_PeriodTp_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name depouserReadSync
 * @description depouser Read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.depouserReadSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_DepoUser",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_DepoUser=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    txb_depo_user.setValue(dts_DepoUser.getCellData(1, "USER_INFO"));
};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const isur_cd = txb_com_cd.getValue();
    const emp_nm = txb_user_nm.getValue();
    const startDate = edt_SDate.getValue();
    const endDate = edt_EDate.getValue();
    const searchGubun = mxr_date_gubun.getValue();
    let market_gubun = js_market;
    if (market_gubun === "9") {
        market_gubun = mxr_market_gubun.getValue();
        if (market_gubun === "A") {
            market_gubun = "";
        }
    }
    url += "&SCREN_ID=" + "ULDSTF40300.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&isur_cd=" + isur_cd;
    url += "&emp_nm=" + emp_nm;
    url += "&startDate=" + startDate;
    url += "&endDate=" + endDate;
    url += "&searchGubun=" + searchGubun;
    url += "&market_gubun=" + market_gubun;
    const sbmOptions = {
        id : "sbm_dts_consultationBookList",
        action : "/ConsultationBookManagement.do",
        ref : "",
        target : "dts_consultationBookList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
